        cylinder(d = bore_d, h = coupler_len + 2 * overcut, $fn = fn_curve);

    // Radial set-screw holes on +X side, from bore axis out through the wall
    for (f = setscrew_pos)
        translate([0, 0, f * coupler_len])
            rotate([0, 90, 0])
                cylinder(d = setscrew_d, h = coupler_od / 2 + overcut, $fn = fn_curve);
