// --- Grip grooves ---
groove_n    = 24;     // number of grooves
groove_d    = 2;      // groove (half-cylinder) diameter, centred on outer surface

// --- Misc ---
eps         = 0.5;    // overshoot for clean cuts

// Derived
flat_x = bore_flat - bore_d / 2;   // flat position from bore centre (1.75 mm)

difference() {
    // Knob body
    cylinder(d = knob_d, h = knob_h);

    // D-shaped blind bore from the bottom face
    translate([0, 0, -eps])
        intersection() {
            cylinder(d = bore_d, h = bore_depth + eps);
            translate([-bore_d / 2 - 1, -bore_d / 2 - 1, -0.01])
                cube([flat_x + bore_d / 2 + 1, bore_d + 2, bore_depth + eps + 0.02]);
        }

    // Vertical grip grooves along full height
    for (i = [0 : groove_n - 1])
        rotate([0, 0, i * 360 / groove_n])
            translate([knob_d / 2, 0, -eps])
                cylinder(d = groove_d, h = knob_h + 2 * eps, $fn = 48);
}
