// Flat drilling / marking jig with 6 x 4 hole grid and orientation notch
// Units: mm. Print orientation: plate flat on bed, z = 0 to plate_t.

$fn = 64;

// --- Plate ---
plate_l = 70;    // plate length along X
plate_w = 50;    // plate width along Y
plate_t = 4;     // plate thickness along Z

// --- Hole grid ---
hole_d   = 3.0;  // through-hole diameter
hole_nx  = 6;    // number of holes along X
hole_ny  = 4;    // number of holes along Y
hole_pitch = 10; // centre-to-centre spacing (X and Y)

// --- Orientation notch (on +Y edge, centred on Y axis) ---
notch_w = 12;    // notch width along X
notch_d = 5;     // notch depth along Y, measured in from +Y edge

// --- Cutting overlap ---
eps = 0.5;       // extension of cutters past the faces they cut

// Grid origin offsets so the grid is centred on the plate
grid_x0 = -(hole_nx - 1) * hole_pitch / 2;
grid_y0 = -(hole_ny - 1) * hole_pitch / 2;

difference() {
    // Plate body, centred in XY, resting on z = 0
    translate([-plate_l / 2, -plate_w / 2, 0])
        cube([plate_l, plate_w, plate_t]);

    // 6 x 4 grid of through-holes
    for (i = [0 : hole_nx - 1])
        for (j = [0 : hole_ny - 1])
            translate([grid_x0 + i * hole_pitch,
                       grid_y0 + j * hole_pitch,
                       -eps])
                cylinder(d = hole_d, h = plate_t + 2 * eps);

    // Rectangular orientation notch in the +Y edge
    translate([-notch_w / 2,
               plate_w / 2 - notch_d,
               -eps])
        cube([notch_w, notch_d + eps, plate_t + 2 * eps]);
}
