box_y      = 55;    // box outer width (Y)
box_z      = 35;    // box outer height (Z)
wall       = 2.0;   // box wall thickness
floor_t    = 2.0;   // box floor thickness

// ---------- Lid ----------
lid_x      = 80;    // lid plate length (X)
lid_y      = 55;    // lid plate width (Y)
lid_t      = 2.5;   // lid plate thickness
lip_x      = 75.4;  // lip outer length (X), 0.3 mm clearance per side
lip_y      = 50.4;  // lip outer width (Y), 0.3 mm clearance per side
lip_wall   = 2.0;   // lip wall thickness
lip_h      = 3.0;   // lip height above plate

// ---------- Layout ----------
gap        = 10;    // gap between parts on the bed
eps        = 0.5;   // overcut for clean differences / overlap for unions

// Centres so the pair is centred on the origin in X
box_cx = -(box_x + gap) / 2;
lid_cx =  (lid_x + gap) / 2;

// ---------- Box (open top) ----------
module box() {
    difference() {
        translate([-box_x/2, -box_y/2, 0])
            cube([box_x, box_y, box_z]);
        translate([-(box_x - 2*wall)/2, -(box_y - 2*wall)/2, floor_t])
            cube([box_x - 2*wall, box_y - 2*wall, box_z - floor_t + eps]);
    }
}

// ---------- Lid (printed upside down) ----------
module lid() {
    union() {
        // Plate
        translate([-lid_x/2, -lid_y/2, 0])
            cube([lid_x, lid_y, lid_t]);
        // Rectangular lip
        difference() {
            translate([-lip_x/2, -lip_y/2, lid_t - 0.01])
                cube([lip_x, lip_y, lip_h + 0.01]);
            translate([-(lip_x - 2*lip_wall)/2, -(lip_y - 2*lip_wall)/2, lid_t - eps])
                cube([lip_x - 2*lip_wall, lip_y - 2*lip_wall, lip_h + 2*eps]);
        }
    }
}

translate([box_cx, 0, 0]) box();
translate([lid_cx, 0, 0]) lid();
