total_h       = 48.0;   // rim height (top of funnel)
wall          = 2.0;    // wall thickness (normal to surface)

// ---------- Derived values ----------
spout_r_out   = spout_od / 2;                 // 5.0
spout_r_in    = spout_r_out - wall;           // 3.0 (6.0 mm bore)
rim_r_out     = rim_od / 2;                   // 27.5
cone_h        = total_h - spout_h;            // 30.0
cone_slope    = (rim_r_out - spout_r_out) / cone_h;   // dr/dz = 0.75
cone_cos      = 1 / sqrt(1 + cone_slope * cone_slope); // cos of half-angle
cone_dr       = wall / cone_cos;              // radial offset for 2 mm normal wall (2.5)
rim_r_in      = rim_r_out - cone_dr;          // inner radius at rim (25.0)
// Height where inner cone surface meets the spout bore
inner_join_z  = spout_h + (spout_r_in - (spout_r_out - cone_dr)) / cone_slope;

// ---------- Model ----------
// Revolved wall cross-section (r, z); open at top and bottom
rotate_extrude($fn = 128)
    polygon(points = [
        [spout_r_out, 0],            // outer spout bottom
        [spout_r_out, spout_h],      // outer spout/cone junction
        [rim_r_out,   total_h],      // outer rim
        [rim_r_in,    total_h],      // inner rim
        [spout_r_in,  inner_join_z], // inner cone/bore junction
        [spout_r_in,  0]             // inner spout bottom
    ]);
